{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"pygments_lexer":"ipython3","nbconvert_exporter":"python","version":"3.6.4","file_extension":".py","codemirror_mode":{"name":"ipython","version":3},"name":"python","mimetype":"text/x-python"},"kaggle":{"accelerator":"none","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"from flask import Flask, render_template, request, redirect, url_for, flash\nfrom qa_bot import answer_question  \nfrom text_summarizer import summarize_text  \nimport secrets\n\napp = Flask(__name__)\n\napp.secret_key = secrets.token_hex(16)  # Generates a 32-character random string\n\n\n\n# Route for the home page\n@app.route(\"/\", methods=[\"GET\", \"POST\"])\ndef home():\n    context = \"\"\n    question = \"\"\n    answer = \"\"\n    \n    if request.method == \"POST\":\n        context = request.form.get(\"context\", \"\")\n        char_count = len(context)\n        \n        # Summarization scenario\n        if 'summarize' in request.form and char_count >= 2000:\n            return redirect(url_for(\"summary\", context=context))\n        \n        # Question Answering scenario\n        elif 'ask_question' in request.form and char_count >= 200:\n            question = request.form.get(\"question\", \"\")\n            if question:\n                answer = answer_question(question, context)\n                # Check for low confidence response\n                if \"I'm sorry\" in answer:\n                    flash(answer)\n                    return redirect(url_for(\"home\", context=context))\n            else:\n                flash(\"Please enter a question.\")\n    \n    return render_template(\"home.html\", context=context, question=question, answer=answer)\n\n# Route for summary result\n@app.route(\"/summary\")\ndef summary():\n    context = request.args.get(\"context\", \"\")\n    summarized_text = summarize_text(context)\n    return render_template(\"summary.html\", summarized_text=summarized_text)\n\nif __name__ == \"__main__\":\n    app.run()\n","metadata":{"_uuid":"bd4bd821-034e-45a6-801e-c9c07eca80b8","_cell_guid":"3ce700a9-7bc6-4792-88f3-a6607d976637","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}